// === Tab: mySketch ===
// https://openprocessing.org/sketch/2315186

let noise3d
let ready = false
let createNoise3D

import('https://cdn.skypack.dev/simplex-noise').then((simplexNoise) => {
	createNoise3D = simplexNoise.createNoise3D 
	noise3d = createNoise3D()
	ready = true
})

let lastTime = 0
let palettes = [
	['#081232', '#bba0ca', '#fff8e8', '#fcd581', '#d52941', '#990d35'],
	['#fefaec', '#f398c3', '#cf3895', '#a0d28d', '#06b4b0', '#fed000', '#FF8552'],
	['#002e2d', '#06b4b0', '#cf3895', '#fff8e8', '#f398c3', '#a0d28d', '#ffd930', '#FF8552'],
	['#331c25', '#3c2e6b', '#0081af', '#a7d6c3', '#285943', '#8a8fbd', '#9a79b8', '#fcee49'],
]
let m, tree, palette, bg

function startTree() {
		let bounds = new Rect((width - m) / 2, (height - m) / 2, m, m)
		let node = new Node({
			bounds,
			depth: 0,
			parent: null
		})
	palette = random(palettes)
	tree = new Tree(node, shuffle(palette.slice(1)))
}

function setup() {
	createCanvas(windowWidth, windowHeight)
	m = Math.max(width, height) * 0.9
	startTree()
}

function draw() {
	clear()
	background(palette[0])

	let ms = millis()
	noStroke()

	if (ready) tree.update(ms)
}

class Tree {
	constructor(node, palette) {
		this.node = node
		this.palette = palette
		this.threshold = 0.7
		this.maxDepth = 6
		this.minDepth = 3
		this.noiseFreq1 = {
			x: 0.8,
			y: 0.8
		}
		this.noiseFreq2 = {
			x: 0.65,
			y: 0.65
		}
		this.noiseSpeed1 = 2.02
		this.noiseSpeed2 = 0.5
		this.minLifeSpan = 1000

		this.stepTime = 0
		this.noiseVals = {}
		this.leaves = this.node.getLeaves()

		this.init()
	}

	init() {
		let minSize = 30
		let maxDepthSize = this.node.rect.w / Math.pow(2, this.maxDepth - 1)
		if (maxDepthSize < minSize) {
			this.maxDepth = Math.floor(Math.log2(this.node.rect.w / minSize)) + 1
			if (this.maxDepth < this.minDepth) this.minDepth = this.maxDepth - 1
		}
		let leaves = this.node.getLeaves()
		let minDepth = leaves.reduce((acc, leaf) => Math.min(acc, leaf.depth), Infinity)
		var bounds = this.node.rect

		let biasX = random(bounds.x, bounds.x + bounds.w)
		let biasY = random(bounds.y, bounds.y + bounds.h)

		while (minDepth < this.minDepth) {
			let leafX = randomBias(bounds.x, bounds.x + bounds.w, biasX, 1.9)
			let leafY = randomBias(bounds.y, bounds.y + bounds.h, biasY, 0.9)
			let leaf = this.node.findNode(leafX, leafY)

			if (leaf && leaf.depth < this.maxDepth) {
				leaf.divide()
			}

			leaves = this.node.getLeaves()
			minDepth = leaves.reduce((acc, leaf) => Math.min(acc, leaf.depth), Infinity)
		}
	}

	getNoiseVals(leaf) {
		let x = leaf.rect.x
		let y = leaf.rect.y
		let key = `${x}-${y}`

		if (!(key in this.noiseVals)) {
			this.noiseVals[key] = {
				n1: noise3d(
					x * (this.noiseFreq1.x / 1000),
					y * (this.noiseFreq1.y / 1000),
					this.noiseSpeed1 * this.stepTime
				),
				n2: noise3d(
					x * (this.noiseFreq2.x / 1000),
					y * (this.noiseFreq2.y / 1000),
					this.noiseSpeed2 * this.stepTime
				)
			}
		}

		return this.noiseVals[key]
	}

	getLeafData(leaf) {
		if (leaf.data) return leaf.data

		let {
			n1,
			n2
		} = this.getNoiseVals(leaf)

		let colorVal = n1 * 0.5 + 0.5
		colorVal += leaf.depth + random(0.5)
		let c1 = Math.floor(colorVal) % this.palette.length
		let c2 = (c1 + 1) % this.palette.length

		let keys = Object.keys(patterns)
		let patternNoise = n1 * 0.5 + 0.5
		let patternVal = Math.floor(patternNoise * keys.length)
		let pattern = keys[patternVal]

		leaf.data = {
			c1,
			c2,
			pattern
		}
		return leaf.data
	}

	draw() {
		this.leaves.forEach((leaf) => {
			let {
				c1,
				c2,
				pattern
			} = this.getLeafData(leaf)
			fill(this.palette[c1])

			patterns[pattern]({
				bounds: leaf.rect,
				col1: this.palette[c1],
				col2: this.palette[c2],
				progress: leaf.progress,
			})
		})
	}

	update(ms) {
		fill(255)

		this.stepTime = ms / 1000
		this.leaves = this.node.getLeaves()
		this.noiseVals = {}

		this.draw()

		this.leaves.forEach((leaf, i) => {
			if (leaf.state !== 'idle') return
			if (leaf.depth >= this.minDepth && leaf.age < this.minLifeSpan) return

			let { n2 } = this.getNoiseVals(leaf)

			if (n2 > this.threshold && leaf.depth < this.maxDepth) {
				leaf.setWillDivide()
			} else if (n2 < -this.threshold && leaf.depth > this.minDepth) {
				if (leaf.parent) {
					leaf.parent.setWillCollapse()
				}
			}
		})
	}
}

function mousePressed() {
	if (ready) {
		noise3d = createNoise3D()
		startTree()
	}
}

// === Tab: patterns ===
const equilateralTriangle = ({ x, y, w, h, progress = 1 }) => {
    let side = Math.min(w, h) * 0.9 * progress
    let hght = (side * Math.sqrt(3)) / 2
    let x2 = x + (w - side) / 2
    let y2 = y + (h - hght) / 2

    beginShape()
    vertex(x2, y2 + hght)
    vertex(x2 + side / 2, y2)
    vertex(x2 + side, y2 + hght)
    endShape(CLOSE)
}

const patterns = {
    circle: ({ bounds, col1, col2, progress = 1 }) => {
        let { x, y, w, h } = bounds
        var m = Math.min(w, h)
        let radius = Math.max((m - 8) * 0.5 * progress, 0)

        push()
        // translate(x + (width - m) / 2, y + (height - m) / 2)
        fill(col1)
        circle(x + m / 2, y + m / 2, radius * 2)
        pop()
    },
    triangle: ({ bounds, col1, col2, progress = 1 }) => {
        let { x, y, w, h } = bounds
        var m = Math.min(w, h)
        m -= m * 0.1

        push()
        translate(x + (w - m) / 2, y + (h - m) / 2)

        if (m < 30) {
            fill(col1)
            noStroke()
        } else {
            stroke(col1)
            strokeWeight(Math.min(5, m * progress * 0.5))
            noFill()
        }
        equilateralTriangle({ x: 0, y: 0, w: m, h: m, progress })

        pop()
    },
    circleOutline: ({ bounds, col1, col2, progress = 1 }) => {
        let { x, y, w, h } = bounds
        var m = Math.min(w, h)
        var radius = Math.max((m - 8) * 0.5, 0)
        let radius1 = Math.max(radius * progress, 0)
        let radius2 = Math.max((radius / 3) * 2 * progress, 0)
        let radius3 = Math.max((radius / 3) * 1 * progress, 0)
        push()

        noStroke()
        fill(col1)
        circle(x + m / 2, y + m / 2, radius1 * 2)
        fill(col2)
        circle(x + m / 2, y + m / 2, radius2 * 2)
        fill(col1)
        circle(x + m / 2, y + m / 2, radius3 * 2)
        pop()
    },
    boxesHorizontal: ({ bounds, col1, col2, progress = 1 }) => {
        let { x, y, w, h } = bounds
        let pad = 4
        let rectW = bounds.w - pad * 2
        let midY = 2
        let rectH = Math.max(bounds.h * 0.5 - pad - midY * 0.5, 4)
        rectH *= progress
        let left = x + (bounds.w - rectW) / 2

        push()
        noStroke()
        fill(col1)
        rect(left, y + bounds.h / 2 - midY / 2 - rectH, rectW, rectH, w, w, 0, 0)

        fill(col2)
        rect(left, y + bounds.h / 2 + midY / 2, rectW, rectH, 0, 0, w, w)

        pop()
    },
    boxesVertical: ({ bounds, col1, col2, progress = 1 }) => {
        let { x, y } = bounds
        var pad = 4
        var rectH = bounds.h - pad * 2
        let midX = 2
        var rectW = Math.max(bounds.w * 0.5 - pad - midX * 0.5, 4)
        rectW *= progress
        let top = y + (bounds.h - rectH) / 2

        noStroke()
        fill(col1)
        rect(x + bounds.w / 2 - midX / 2 - rectW, top, rectW, rectH, bounds.w, 0, 0, bounds.w)

        fill(col2)
        rect(x + bounds.w / 2 + midX / 2, top, rectW, rectH, 0, bounds.w, bounds.w, 0)
    },
}


// === Tab: node ===
class Rect {
	constructor(x, y, w, h) {
		this.x = x
		this.y = y
		this.w = w
		this.h = h
	}

	contains(x, y) {
		return x >= this.x && x <= this.x + this.w && y >= this.y && y <= this.y + this.h
	}
}

class Node {
	constructor({
		bounds,
		depth = 0,
		parent = null
	}) {
		this.rect = bounds
		this.depth = depth
		this.parent = parent
		this.children = []
		this.objects = []
		this.duration = 400

		this.state = 'entering'
		this.birthday = Date.now()
		this.easeEnter = 'easeOutSin'
		this.easeLeave = 'easeOutSin'

		this.data = null
		this.progress = 0

		this.tween = p5.tween.manager
			.addTween(this)
			.addMotion('progress', 1, this.duration, this.easeEnter)
			.startTween()
			.onEnd(() => {
				this.state = 'idle'
			})
	}

	get age() {
		return Date.now() - this.birthday
	}

	setWillDivide() {
		if (this.state !== 'idle' || this.children.length > 0) {
			return false
		}
		this.state = 'willDivide'

		this.tween = p5.tween.manager
			.addTween(this)
			.addMotion('progress', 0, this.duration, this.easeLeave)
			.startTween()
			.onEnd(() => {
				this.divide()
				this.state = 'idle'
			})
	}

	divide() {
		if (this.children.length > 0) return false

		let w = this.rect.w / 2
		let h = this.rect.h / 2

		this.children = [
			new Node({
				bounds: new Rect(this.rect.x, this.rect.y, w, h),
				depth: this.depth + 1,
				parent: this,
			}),
			new Node({
				bounds: new Rect(this.rect.x + w, this.rect.y, w, h),
				depth: this.depth + 1,
				parent: this,
			}),
			new Node({
				bounds: new Rect(this.rect.x, this.rect.y + h, w, h),
				depth: this.depth + 1,
				parent: this,
			}),
			new Node({
				bounds: new Rect(this.rect.x + w, this.rect.y + h, w, h),
				depth: this.depth + 1,
				parent: this,
			}),
		]
		this.progress = 1
		this.state = 'idle'

		return true
	}

	setWillCollapse() {
		if (this.state !== 'idle') return false

		if (this.children.length === 0) {
			this.state = 'parentWillCollapse'
			return new Promise((resolve) => {
				this.tween = p5.tween.manager
					.addTween(this)
					.addMotion('progress', 0, this.duration, this.easeLeave)
					.startTween()
					.onEnd(() => {
						this.state = 'idle'
						resolve()
					})
			})
		}

		var leaves = this.getLeaves()
		let canCollapse = !leaves.some((leaf) => leaf.state !== 'idle')
		if (!canCollapse) return false

		let promises = []
		for (let i = 0; i < leaves.length; i++) {
			var leaf = leaves[i]
			let leafPromise = leaf.setWillCollapse()
			if (!leafPromise) return false
			promises.push(leafPromise)
		}

		this.state = 'willCollapse'
		return Promise.all(promises).then(() => {
			this.collapse()
		})
	}

	collapse() {
		// if (this.children.length === 0) return false
		this.state = 'entering'
		this.progress = 0
		this.tween = p5.tween.manager
			.addTween(this)
			.addMotion('progress', 1, this.duration, this.easeLeave)
			.startTween()
			.onEnd(() => {
				this.state = 'idle'
			})

		this.children = []
		return true
	}

	getLeaves() {
		var leaves = []
		if (this.children.length === 0) {
			leaves.push(this)
		} else {
			this.children.forEach((child) => {
				leaves.push(...child.getLeaves())
			})
		}
		return leaves
	}

	getAll() {
		let nodes = []
		nodes.push(this)
		this.children.forEach((child) => {
			nodes.push(...child.getAll())
		})
		return nodes
	}

	clear() {
		this.children = []
	}

	findNode(x, y) {
		if (!this.rect.contains(x, y)) return false

		if (this.children.length === 0) {
			return this
		}

		for (let i = 0; i < this.children.length; i++) {
			let child = this.children[i]
			var node = child.findNode(x, y)
			if (node) return node
		}

		return false
	}

	getMaxDepth() {
		let depths = this.children.map((child) => child.getMaxDepth())
		return depths.length > 0 ? Math.max(...depths) : this.depth
	}
}

// === Tab: utils ===
// https://github.com/georgedoescode/generative-utils/blob/master/src/randomBias.js
function randomBias(min, max, bias, influence = 0.5) {
	const base = random(min, max)
	const mix = random(0, 1) * influence
	return base * (1 - mix) + bias * mix
}

